// PASTE THE MERGE ROWS HERE.
//
// Produced by: python3 automation/mint-unsubscribe-tokens.py pt-backlog.csv \
//                --source coachmatch-pt-backlog-2026-09
// then convert that CSV to JSON:
//   python3 -c "import csv,json;print(json.dumps(list(csv.DictReader(open('coachmatch-pt-backlog-2026-09-merge.csv'))),ensure_ascii=False,indent=1))"
//
// Each row needs: firstname, email, lang, token, unsubscribe_url
// Keep this list in the workflow rather than reading a file: this is a ONE-OFF
// send, the list is 30 rows, and having the exact recipients frozen inside the
// execution record is worth more here than the elegance of a file read.

const RECIPIENTS = [
  // { "firstname": "...", "email": "...", "lang": "PORTUGUESE", "token": "...", "unsubscribe_url": "https://..." },
];

if (!RECIPIENTS.length) {
  throw new Error('RECIPIENTS is empty -- paste the merge rows before running.');
}
for (const r of RECIPIENTS) {
  if (!r.email || !r.unsubscribe_url) {
    throw new Error(`recipient missing email or unsubscribe_url: ${JSON.stringify(r)}`);
  }
}

return RECIPIENTS.map((json) => ({ json }));

